#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Global timer ID to be managed
timer_t global_timerid;

// Signal handler required for POSIX timers (minimal implementation)
static void timer_handler(int sig, siginfo_t *si, void *uc) 
{ 
    // In a real application, timer actions would occur here
    (void)sig; (void)si; (void)uc;
}

int main() 
{
    struct sigevent sev;
    struct sigaction sa;

    // 1. Setup signal handler for SIGRTMIN
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // 2. Setup sigevent structure for notification
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &global_timerid;

    // 3. Create the timer
    if (timer_create(CLOCK_REALTIME, &sev, &global_timerid) == -1) {
        perror("timer_create");
        return EXIT_FAILURE;
    }
    printf("Timer successfully created.\n");

    // 4. Delete the timer, releasing resources
    if (timer_delete(global_timerid) == -1) {
        // Check if the timer ID might have been invalid due to a race or error
        if (errno == EINVAL) {
            fprintf(stderr, "Error: Timer ID is invalid.\n");
        } else {
            perror("timer_delete");
        }
        return EXIT_FAILURE;
    }

    printf("Timer successfully deleted and resources released.\n");

    // Trying to delete the same timer again should fail with EINVAL
    if (timer_delete(global_timerid) == -1 && errno == EINVAL) {
        printf("Attempting to delete the timer again correctly returns EINVAL.\n");
    }

    return EXIT_SUCCESS;
}
// Compile with: gcc -o timer_del example.c -lrt
